'use strict';
// A take stays outside the project until the user explicitly commits it.
class StudioTakeRecorder {
  constructor({requestStream,makeRecorder,decode,onChange=()=>{},limit=59000}){Object.assign(this,{requestStream,makeRecorder,decode,onChange,limit});this.phase='idle';this.epoch=0;this.stream=null;this.recorder=null;this.draft=null;this.error='';this.timer=null;this.started=0}
  emit(phase){this.phase=phase;this.onChange(this)}
  closeStream(){clearTimeout(this.timer);this.timer=null;if(this.stream){this.stream.getTracks().forEach(t=>{t.onended=null;t.stop()});this.stream=null}}
  async connect(){if(!['idle','error'].includes(this.phase))return;const epoch=++this.epoch;this.error='';this.emit('requesting');try{const stream=await this.requestStream();if(epoch!==this.epoch){stream.getTracks().forEach(t=>t.stop());return}this.stream=stream;for(const t of stream.getTracks())t.onended=()=>this.fail('Le micro a été déconnecté. Rebranche-le puis réessaie.');this.emit('ready')}catch(e){if(epoch===this.epoch)this.fail(e)}}
  start(){if(this.phase!=='ready')return;const epoch=this.epoch,chunks=[];try{const recorder=this.makeRecorder(this.stream);this.recorder=recorder;this.done=new Promise(resolve=>this.resolveDone=resolve);const finish=this.resolveDone;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onerror=()=>{if(epoch===this.epoch)this.fail('La prise a été interrompue. Réessaie.')};recorder.onstop=async()=>{if(epoch!==this.epoch)return;this.closeStream();this.recorder=null;this.emit('decoding');try{const data=await this.decode(new Blob(chunks,{type:recorder.mimeType}));if(epoch!==this.epoch)return;if(!data?.data||data.data.length<2)throw Error('La prise est vide. Recommence.');this.draft=data;this.emit('review')}catch(e){if(epoch===this.epoch)this.fail(e)}finally{finish();if(this.resolveDone===finish)this.resolveDone=null}};recorder.start();this.started=Date.now();this.timer=setTimeout(()=>this.stop(),this.limit);this.emit('recording')}catch(e){this.fail(e)}}
  stop(){if(this.phase==='recording'){clearTimeout(this.timer);this.emit('stopping');try{this.recorder.stop()}catch(e){this.fail(e)}}return this.done}
  fail(e){this.error=e?.name==='NotAllowedError'?'Accès au micro refusé. Autorise le micro dans les réglages du navigateur, puis réessaie.':e?.name==='NotFoundError'?'Aucun micro détecté. Branche un micro ou vérifie ton appareil.':typeof e==='string'?e:e?.message||'Le micro est indisponible. Réessaie.';this.epoch++;try{if(this.recorder?.state==='recording')this.recorder.stop()}catch{}this.recorder=null;this.closeStream();this.resolveDone?.();this.resolveDone=null;this.emit('error')}
  discard(){this.epoch++;try{if(this.recorder?.state==='recording')this.recorder.stop()}catch{}this.recorder=null;this.closeStream();this.resolveDone?.();this.resolveDone=null;this.draft=null;this.error='';this.emit('idle')}
}
if(typeof module!=='undefined')module.exports=StudioTakeRecorder;
